<fieldset class="manual-set" data-manual-set><legend>Set <?php echo esc_html($i+1); ?></legend><div class="manual-set-fields">
<?php foreach(array('type'=>array('Set type',array('active'=>'Swim','rest'=>'Rest')),'repetitions'=>array('Repetitions',null),'distance'=>array('Distance per repetition (pool unit)',null),'stroke'=>array('Stroke',array('UNKNOWN'=>'Unknown','FR'=>'Freestyle','BR'=>'Breaststroke','BACK'=>'Backstroke','FLY'=>'Butterfly','MIXED'=>'Mixed')),'timing'=>array('Timing mode',array('unknown'=>'Untimed / unknown','measured_rep'=>'Measured repetitions','measured_set'=>'Measured whole set','interval'=>'Interval / send-off','derived'=>'Derived / estimated')),'rep_times'=>array('Measured repetition times (comma separated)',null),'set_time'=>array('Measured set time',null),'interval'=>array('Interval / send-off',null),'rest'=>array('Rest time',null),'notes'=>array('Set notes',null))as$key=>$field): ?><label><span><?php echo esc_html($field[0]); ?></span><?php if(is_array($field[1])): ?><select data-field="<?php echo esc_attr($key); ?>" name="sets[<?php echo esc_attr($i); ?>][<?php echo esc_attr($key); ?>]" aria-label="<?php echo esc_attr('Set '.($i+1).': '.$field[0]); ?>"><?php foreach($field[1]as$value=>$label): ?><option value="<?php echo esc_attr($value); ?>" <?php selected($row[$key],$value); ?>><?php echo esc_html($label); ?></option><?php endforeach; ?></select><?php else: ?><input data-field="<?php echo esc_attr($key); ?>" name="sets[<?php echo esc_attr($i); ?>][<?php echo esc_attr($key); ?>]" aria-label="<?php echo esc_attr('Set '.($i+1).': '.$field[0]); ?>" value="<?php echo esc_attr($row[$key]); ?>" maxlength="6000" <?php if(in_array($key,array('distance','repetitions'),true))echo 'type="number" min="0" step="'.($key==='distance'?'0.001':'1').'"'; ?> ><?php endif; ?></label><?php endforeach; ?></div><div class="plan-actions"><button type="button" class="control" data-set-up>Move set up</button><button type="button" class="control" data-set-down>Move set down</button><button type="button" class="control" data-remove-set>Remove set</button></div></fieldset>
